  constructor(message, exitCode) {
    super(message);
    this.exitCode = exitCode;
  }
}

function readError(name, reason) {
  return new CliError(`Error: ${name}: ${reason}`, 1);
}

function dataError(name, reason) {
  return new CliError(`Error: ${name}: ${reason}`, 3);
}

